/**
 * Google Photorealistic 3D scene — ONE persistent Map3DElement per session.
 *
 * Owns the 3D element plus everything drawn on it: route ribbons, the live
 * trail, memory light pillars, HTML markers (photo beads, tents, faces) and
 * the vehicle model. Never torn down between Atlas / Trip focus / Watch —
 * that was the source of the old "pause turns 2D" flash and of one billable
 * Immersive Maps load per Play.
 */

import { haversineMeters, type Camera3D, type TravelMode } from "./camera-math";

type LatLngAlt = { lat: number; lng: number; altitude?: number };

export type Map3DEl = HTMLElement & {
  mode: string;
  center: LatLngAlt;
  heading: number;
  tilt: number;
  range: number;
  roll?: number;
  fov?: number;
  minTilt?: number;
  maxTilt?: number;
  maxAltitude?: number;
  defaultUIHidden?: boolean;
  flyCameraTo?: (opts: { endCamera: Record<string, unknown>; durationMillis: number }) => void;
  flyCameraAround?: (opts: {
    camera: Record<string, unknown>;
    durationMillis: number;
    rounds?: number;
    repeatCount?: number;
  }) => void;
  stopCameraAnimation?: () => void;
};

type Polyline3DEl = HTMLElement & {
  path?: LatLngAlt[];
  coordinates?: LatLngAlt[];
  strokeColor: string;
  strokeWidth: number;
  outerColor?: string;
  outerWidth?: number;
  altitudeMode?: string;
  drawsOccludedSegments?: boolean;
  zIndex?: number;
  geodesic?: boolean;
};

type Marker3DEl = HTMLElement & {
  position: LatLngAlt;
  altitudeMode?: string;
  extruded?: boolean;
  sizePreserved?: boolean;
  zIndex?: number;
};

type HtmlMarkerEl = HTMLElement & {
  position: LatLngAlt;
  altitudeMode?: string;
  anchorLeft?: string;
  anchorTop?: string;
};

type Model3DEl = HTMLElement & {
  src: string;
  position: LatLngAlt;
  orientation?: { heading: number; tilt: number; roll: number };
  scale?: number | { x: number; y: number; z: number };
  altitudeMode?: string;
};

export type Maps3dLib = {
  Map3DElement: new (opts?: Record<string, unknown>) => Map3DEl;
  Polyline3DElement: new (opts?: Record<string, unknown>) => Polyline3DEl;
  Marker3DElement: new (opts?: Record<string, unknown>) => Marker3DEl;
  MarkerElement?: new (opts?: Record<string, unknown>) => HtmlMarkerEl;
  Model3DElement?: new (opts?: Record<string, unknown>) => Model3DEl;
  AltitudeMode?: Record<string, string>;
  MapMode?: Record<string, string>;
};

export type RouteStyle = {
  color: string;
  /** Core stroke width in CSS px. */
  width: number;
  /** 0–1 opacity of the core stroke. */
  alpha: number;
  casingColor?: string;
  /** Casing thickness per side in CSS px. */
  casingWidth?: number;
  casingAlpha?: number;
  visible: boolean;
  zIndex?: number;
};

export type SceneMarkerOptions = {
  anchor?: "center" | "bottom" | string;
  offset?: [number, number];
  rotateWithMap?: boolean;
  zIndex?: number;
};

export type SceneMarker = {
  element: HTMLElement;
  setPosition: (lat: number, lng: number) => void;
  setRotation: (deg: number) => void;
  remove: () => void;
};

type RouteRecord = {
  el: Polyline3DEl;
  coords: LatLngAlt[];
  /** Cheap geometry fingerprint — skips re-uploading 1k-point paths on every restyle. */
  sig: string;
  style: RouteStyle;
  attached: boolean;
  drawOnToken: number;
};

function pathSignature(path: LatLngAlt[]): string {
  if (!path.length) return "0";
  const a = path[0];
  const z = path[path.length - 1];
  const m = path[path.length >> 1];
  return `${path.length}:${a.lat},${a.lng}:${m.lat},${m.lng}:${z.lat},${z.lng}`;
}

type SceneEvent = "gesture" | "steady" | "headingchange" | "animationend" | "camerachange";

declare global {
  interface Window {
    /** Test seam: Playwright injects a fake maps3d library factory. */
    __MMD_MAPS3D_FACTORY__?: () => Promise<Maps3dLib> | Maps3dLib;
    /** Debug/verify hook: the live Map3DElement when the 3D scene is active. */
    __MMD_MAP3D?: Map3DEl | null;
  }
}

export const SCENE_HOST_ID = "map-3d-scene";
/** Orientation offsets for the vehicle glb (model frame: +Y nose, +Z up). */
export const VEHICLE_MODEL_ORIENTATION = { heading: 0, tilt: 0, roll: 0 };
export const VEHICLE_MODEL_URL = "./models/car.glb";

let maps3dPromise: Promise<Maps3dLib | null> | null = null;

function mockRequested(): boolean {
  try {
    return new URLSearchParams(window.location.search).get("mmd3d") === "mock";
  } catch {
    return false;
  }
}

/** Load the maps3d library once (or the test double when requested). */
export async function loadMaps3dLibrary(): Promise<Maps3dLib | null> {
  if (maps3dPromise) return maps3dPromise;
  maps3dPromise = (async () => {
    try {
      if (typeof window.__MMD_MAPS3D_FACTORY__ === "function") {
        return await window.__MMD_MAPS3D_FACTORY__();
      }
      if (mockRequested()) {
        const mod = await import("./maps3d-mock");
        return mod.createMockMaps3d();
      }
      if (!window.google?.maps?.importLibrary) return null;
      const lib = (await window.google.maps.importLibrary("maps3d")) as Maps3dLib;
      if (!lib?.Map3DElement) return null;
      return lib;
    } catch (err) {
      console.warn("[mmd] maps3d unavailable", err);
      return null;
    }
  })();
  return maps3dPromise;
}

/** Cheap WebGL probe — Map3D needs hardware WebGL2; software GL fails silently. */
export function probeWebGL(): boolean {
  try {
    const c = document.createElement("canvas");
    const gl = c.getContext("webgl2") || c.getContext("webgl");
    return !!gl;
  } catch {
    return false;
  }
}

function parseColor(color: string): [number, number, number, number] | null {
  const s = String(color || "").trim();
  const hex = s.match(/^#([0-9a-f]{3,8})$/i);
  if (hex) {
    let h = hex[1];
    if (h.length === 3 || h.length === 4) h = h.split("").map((c) => c + c).join("");
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b = parseInt(h.slice(4, 6), 16);
    const a = h.length === 8 ? parseInt(h.slice(6, 8), 16) / 255 : 1;
    return [r, g, b, a];
  }
  const rgb = s.match(/^rgba?\(([^)]+)\)$/i);
  if (rgb) {
    const parts = rgb[1].split(/[\s,/]+/).filter(Boolean).map(Number);
    if (parts.length >= 3) return [parts[0], parts[1], parts[2], parts[3] ?? 1];
  }
  return null;
}

/** CSS color with an explicit alpha (Polyline3D has no opacity property). */
export function withAlpha(color: string, alpha: number): string {
  const a = Math.max(0, Math.min(1, alpha));
  const p = parseColor(color);
  if (!p) return color;
  return `rgba(${p[0]}, ${p[1]}, ${p[2]}, ${(p[3] * a).toFixed(3)})`;
}

export class Google3DScene {
  readonly host: HTMLElement;
  private el: Map3DEl | null = null;
  private lib: Maps3dLib | null = null;
  private active = false;
  private routes = new Map<string, RouteRecord>();
  private trailEl: Polyline3DEl | null = null;
  private trailTimer: number | null = null;
  private trailPending: { coords: LatLngAlt[]; color: string } | null = null;
  private lastTrailWrite = 0;
  private pillars: Polyline3DEl[] = [];
  private markers = new Set<HTMLElement>();
  private rotatingMarkers = new Set<{ apply: () => void }>();
  private vehicle: Model3DEl | null = null;
  private vehicleOk: boolean | null = null;
  private listeners = new Map<SceneEvent, Set<(payload?: unknown) => void>>();
  private steadyState = false;
  private steadyWaiters: Array<(ok: boolean) => void> = [];
  private animationWaiters: Array<() => void> = [];
  private mode: "HYBRID" | "SATELLITE" = "HYBRID";
  /** Pointer currently down on the scene (not cinema chrome). */
  private pointerDown = false;
  private pointerCount = 0;
  /** True after a confirmed pan/zoom/pinch — bare taps stay false. */
  private exploreArmed = false;
  private camAtPointerDown: Camera3D | null = null;

  constructor(hostParent: HTMLElement) {
    // Provider switch / failed teardown can leave an orphaned host — never stack two scenes.
    try {
      hostParent.querySelectorAll(`#${SCENE_HOST_ID}, .map-3d-scene`).forEach((n) => n.remove());
    } catch {
      /* ignore */
    }
    this.host = document.createElement("div");
    this.host.id = SCENE_HOST_ID;
    this.host.className = "map-3d-scene";
    this.host.setAttribute("aria-hidden", "true");
    hostParent.appendChild(this.host);
  }

  isActive(): boolean {
    return this.active && !!this.el;
  }

  get element(): Map3DEl | null {
    return this.el;
  }

  get library(): Maps3dLib | null {
    return this.lib;
  }

  supportsHtmlMarkers(): boolean {
    return !!this.lib?.MarkerElement;
  }

  supportsModels(): boolean {
    return !!this.lib?.Model3DElement;
  }

  on(event: SceneEvent, fn: (payload?: unknown) => void): () => void {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event)!.add(fn);
    return () => this.listeners.get(event)?.delete(fn);
  }

  private emit(event: SceneEvent, payload?: unknown): void {
    this.listeners.get(event)?.forEach((fn) => {
      try {
        fn(payload);
      } catch (err) {
        console.error(err);
      }
    });
  }

  /** Create the Map3DElement and wait for its WebGL canvas. False → caller falls back to 2D. */
  async boot(initial: Camera3D & { mode?: "HYBRID" | "SATELLITE" }, timeoutMs = 12_000): Promise<boolean> {
    if (this.active && this.el) return true;
    if (!probeWebGL()) {
      console.warn("[mmd] WebGL unavailable — 3D scene disabled");
      return false;
    }
    this.lib = await loadMaps3dLibrary();
    if (!this.lib) {
      // Allow a later Retry 3D / provider switch to re-import maps3d.
      maps3dPromise = null;
      return false;
    }
    try {
      this.mode = initial.mode || "HYBRID";
      const mode = this.lib.MapMode?.[this.mode] || this.mode;
      const el = new this.lib.Map3DElement({
        mode,
        center: { lat: initial.lat, lng: initial.lng, altitude: 0 },
        heading: initial.heading,
        tilt: initial.tilt,
        range: initial.range,
        gestureHandling: "GREEDY",
        defaultUIHidden: true,
        maxTilt: 82,
      });
      el.style.cssText = "position:absolute;inset:0;width:100%;height:100%;border:0;display:block;";
      this.host.innerHTML = "";
      this.host.appendChild(el);
      this.el = el;
      this.applyFovForViewport();
      document.body.classList.add("google-3d-booting");
      this.bindElementEvents(el);

      const ready = await this.waitForCanvas(el, timeoutMs);
      document.body.classList.remove("google-3d-booting");
      if (!ready) {
        console.warn("[mmd] Map3D canvas never appeared — falling back to 2D hybrid");
        this.teardownElement();
        maps3dPromise = null;
        return false;
      }
      this.active = true;
      this.host.setAttribute("aria-hidden", "false");
      document.body.classList.add("google-3d");
      window.__MMD_MAP3D = el;
      return true;
    } catch (err) {
      document.body.classList.remove("google-3d-booting");
      console.warn("[mmd] Map3DElement failed to start", err);
      this.teardownElement();
      maps3dPromise = null;
      return false;
    }
  }

  private bindElementEvents(el: Map3DEl): void {
    el.addEventListener("gmp-steadychange", (ev: Event) => {
      const steady = !!(ev as Event & { isSteady?: boolean }).isSteady;
      this.steadyState = steady;
      if (steady) {
        const waiters = this.steadyWaiters;
        this.steadyWaiters = [];
        waiters.forEach((w) => w(true));
      }
      this.emit("steady", steady);
    });
    el.addEventListener("gmp-animationend", () => {
      const waiters = this.animationWaiters;
      this.animationWaiters = [];
      waiters.forEach((w) => w());
      this.emit("animationend");
    });
    el.addEventListener("gmp-headingchange", () => {
      this.rotatingMarkers.forEach((m) => m.apply());
      this.emit("headingchange", el.heading);
      this.maybeArmExploreFromCamera("heading");
    });
    el.addEventListener("gmp-centerchange", () => {
      this.emit("camerachange");
      this.maybeArmExploreFromCamera("pan");
    });
    // Range / tilt may fire on some Map3D builds; ignore if unsupported.
    try {
      el.addEventListener("gmp-rangechange", () => this.maybeArmExploreFromCamera("zoom"));
    } catch {
      /* older maps3d */
    }
    try {
      el.addEventListener("gmp-tiltchange", () => this.maybeArmExploreFromCamera("tilt"));
    } catch {
      /* older maps3d */
    }

    // Confirmed explore only — bare taps must NOT steal the chase camera
    // (that froze the frame for 4.5s while the car drove off-screen).
    this.host.addEventListener(
      "pointerdown",
      (e) => {
        if (this.isChromeTarget(e.target)) return;
        this.pointerDown = true;
        this.pointerCount += 1;
        this.exploreArmed = false;
        this.camAtPointerDown = this.getCamera();
      },
      { passive: true },
    );
    const endPointer = () => {
      this.pointerCount = Math.max(0, this.pointerCount - 1);
      if (this.pointerCount === 0) {
        this.pointerDown = false;
        this.exploreArmed = false;
        this.camAtPointerDown = null;
      }
    };
    this.host.addEventListener("pointerup", endPointer, { passive: true });
    this.host.addEventListener("pointercancel", () => {
      this.pointerDown = false;
      this.pointerCount = 0;
      this.exploreArmed = false;
      this.camAtPointerDown = null;
    }, { passive: true });
    this.host.addEventListener(
      "wheel",
      (e) => {
        if (this.isChromeTarget(e.target)) return;
        if (Math.abs(e.deltaY) < 0.5 && Math.abs(e.deltaX) < 0.5) return;
        this.emitExplore("wheel");
      },
      { passive: true },
    );
    this.host.addEventListener(
      "touchstart",
      (e) => {
        if (this.isChromeTarget(e.target)) return;
        if (e.touches.length >= 2) this.emitExplore("pinch");
      },
      { passive: true },
    );
  }

  /** Cinema Rail / HUD / memory chrome — never treat as a map explore gesture. */
  private isChromeTarget(target: EventTarget | null): boolean {
    const node = target as HTMLElement | null;
    if (!node || typeof node.closest !== "function") return false;
    return !!node.closest(
      ".cinema-rail, .watch-transport, #watch-hud, .hud-stack, .memory-pop, .cinema-title, .letterbox, button, input, a, .rail-legend",
    );
  }

  private camMovedEnough(): boolean {
    if (!this.camAtPointerDown) return false;
    const cur = this.getCamera();
    const dCenter = haversineMeters(
      this.camAtPointerDown.lat,
      this.camAtPointerDown.lng,
      cur.lat,
      cur.lng,
    );
    const dRange = Math.abs(
      Math.log(Math.max(60, cur.range)) - Math.log(Math.max(60, this.camAtPointerDown.range)),
    );
    const dTilt = Math.abs(cur.tilt - this.camAtPointerDown.tilt);
    const dHead = Math.abs((((cur.heading - this.camAtPointerDown.heading + 540) % 360) - 180));
    return dCenter > 8 || dRange > 0.04 || dTilt > 1.5 || dHead > 2;
  }

  private maybeArmExploreFromCamera(kind: string): void {
    if (!this.pointerDown || this.exploreArmed) return;
    if (!this.camMovedEnough()) return;
    this.emitExplore(kind);
  }

  private emitExplore(kind: string): void {
    if (this.exploreArmed) return;
    this.exploreArmed = true;
    this.emit("gesture", { kind, explore: true });
  }

  private waitForCanvas(root: HTMLElement, timeoutMs: number): Promise<boolean> {
    return new Promise((resolve) => {
      const start = performance.now();
      const tick = () => {
        const canvas =
          root.querySelector("canvas") ||
          this.host.querySelector("canvas") ||
          (root.shadowRoot && root.shadowRoot.querySelector("canvas"));
        if (canvas) {
          resolve(true);
          return;
        }
        if (performance.now() - start > timeoutMs) {
          resolve(false);
          return;
        }
        requestAnimationFrame(tick);
      };
      tick();
    });
  }

  private teardownElement(): void {
    this.active = false;
    this.host.innerHTML = "";
    this.el = null;
    this.trailEl = null;
    this.trailSettledEl = null;
    this.trailHeadEl = null;
    this.trailPartsColor = "";
    this.routes.clear();
    this.pillars = [];
    this.markers.clear();
    this.rotatingMarkers.clear();
    this.vehicle = null;
    this.host.setAttribute("aria-hidden", "true");
    document.body.classList.remove("google-3d", "google-3d-booting");
    if (window.__MMD_MAP3D) window.__MMD_MAP3D = null;
  }

  /** Resolve when tiles for the current view have finished rendering (or after timeoutMs). */
  whenSteady(timeoutMs = 4000): Promise<boolean> {
    if (!this.el) return Promise.resolve(false);
    if (this.steadyState) return Promise.resolve(true);
    return new Promise((resolve) => {
      let done = false;
      const finish = (ok: boolean) => {
        if (done) return;
        done = true;
        resolve(ok);
      };
      this.steadyWaiters.push(finish);
      window.setTimeout(() => finish(false), timeoutMs);
    });
  }

  isSteady(): boolean {
    return this.steadyState;
  }

  setMode(mode: "HYBRID" | "SATELLITE"): void {
    if (!this.el) return;
    this.mode = mode;
    const next = this.lib?.MapMode?.[mode] || mode;
    try {
      // Always write — early-return on this.mode === mode left Watch stuck on HYBRID
      // when the element ignored a prior set (ghosted street labels on device).
      this.el.mode = next;
      const got = String(this.el.mode || "").toUpperCase();
      if (got && got !== mode && got !== String(next).toUpperCase()) {
        console.warn("[mmd] Map3D mode read-back mismatch", { want: mode, got: this.el.mode });
        // Retry once on the next frame.
        requestAnimationFrame(() => {
          try {
            if (this.el) this.el.mode = next;
          } catch {
            /* ignore */
          }
        });
      }
    } catch (err) {
      console.warn("[mmd] Map3D mode change failed", err);
    }
  }

  getMode(): "HYBRID" | "SATELLITE" {
    return this.mode;
  }

  // ── Camera ───────────────────────────────────────────────────────────────

  /**
   * Wider lens on narrow screens so a portrait phone frames the US corridor
   * from a sane range instead of 10,000 km out. Read back defensively — older
   * API builds without `fov` keep the 35° default and the math stays honest.
   */
  applyFovForViewport(): void {
    const el = this.el;
    if (!el) return;
    const w = this.host.clientWidth || window.innerWidth || 1200;
    const want = w <= 640 ? 46 : w <= 1180 ? 40 : 35;
    try {
      if ("fov" in el) el.fov = want;
    } catch {
      /* ignore */
    }
  }

  getFov(): number {
    const f = this.el?.fov;
    return typeof f === "number" && f >= 5 && f <= 80 ? f : 35;
  }

  getCamera(): Camera3D {
    const el = this.el;
    if (!el) return { lat: 36.8, lng: -109.5, range: 5_000_000, tilt: 45, heading: 0, roll: 0 };
    const c = el.center || { lat: 36.8, lng: -109.5 };
    return {
      lat: Number(c.lat) || 0,
      lng: Number(c.lng) || 0,
      altitude: Number(c.altitude) || 0,
      range: Number(el.range) || 1000,
      tilt: Number(el.tilt) || 0,
      heading: Number(el.heading) || 0,
      roll: Number(el.roll) || 0,
    };
  }

  /** Direct per-frame camera write (no animation). */
  setCamera(cam: Partial<Camera3D>): void {
    const el = this.el;
    if (!el) return;
    try {
      if (cam.lat != null && cam.lng != null) {
        const prev = Number(el.center?.altitude);
        const altitude =
          cam.altitude != null && Number.isFinite(cam.altitude) ? cam.altitude : Number.isFinite(prev) ? prev : 0;
        el.center = { lat: cam.lat, lng: cam.lng, altitude };
      }
      if (cam.heading != null) el.heading = ((cam.heading % 360) + 360) % 360;
      if (cam.tilt != null) el.tilt = Math.max(0, Math.min(82, cam.tilt));
      if (cam.range != null) el.range = Math.max(60, cam.range);
      if (cam.roll != null && "roll" in el) el.roll = Math.max(-8, Math.min(8, cam.roll));
    } catch (err) {
      console.warn("[mmd] Map3D camera write failed", err);
    }
  }

  private cameraOptions(cam: Partial<Camera3D>): Record<string, unknown> {
    const cur = this.getCamera();
    const altitude = cam.altitude != null && Number.isFinite(cam.altitude) ? cam.altitude : cur.altitude ?? 0;
    return {
      center: { lat: cam.lat ?? cur.lat, lng: cam.lng ?? cur.lng, altitude },
      heading: ((cam.heading ?? cur.heading) % 360 + 360) % 360,
      tilt: Math.max(0, Math.min(82, cam.tilt ?? cur.tilt)),
      range: Math.max(60, cam.range ?? cur.range),
      roll: cam.roll ?? 0,
    };
  }

  /** Parabolic flight; resolves on gmp-animationend (or a duration-based timeout). */
  flyTo(cam: Partial<Camera3D>, durationMs: number): Promise<void> {
    const el = this.el;
    if (!el) return Promise.resolve();
    if (durationMs <= 0 || typeof el.flyCameraTo !== "function") {
      this.setCamera(cam);
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        resolve();
      };
      this.animationWaiters.push(finish);
      try {
        el.flyCameraTo!({ endCamera: this.cameraOptions(cam), durationMillis: Math.round(durationMs) });
      } catch (err) {
        console.warn("[mmd] flyCameraTo failed", err);
        this.setCamera(cam);
        finish();
        return;
      }
      window.setTimeout(finish, durationMs + 600);
    });
  }

  /** Orbit around cam.center. `rounds` may be fractional. */
  flyAround(cam: Partial<Camera3D>, durationMs: number, rounds = 1): Promise<void> {
    const el = this.el;
    if (!el) return Promise.resolve();
    if (typeof el.flyCameraAround !== "function") {
      this.setCamera(cam);
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      let done = false;
      const finish = () => {
        if (done) return;
        done = true;
        resolve();
      };
      this.animationWaiters.push(finish);
      try {
        el.flyCameraAround!({
          camera: this.cameraOptions(cam),
          durationMillis: Math.round(durationMs),
          rounds,
          repeatCount: rounds,
        });
      } catch (err) {
        console.warn("[mmd] flyCameraAround failed", err);
        finish();
        return;
      }
      window.setTimeout(finish, durationMs + 600);
    });
  }

  stopAnimation(): void {
    try {
      this.el?.stopCameraAnimation?.();
    } catch {
      /* ignore */
    }
    const waiters = this.animationWaiters;
    this.animationWaiters = [];
    waiters.forEach((w) => w());
  }

  // ── Routes ───────────────────────────────────────────────────────────────

  private altitudeMode(name: "CLAMP_TO_GROUND" | "RELATIVE_TO_GROUND" | "RELATIVE_TO_MESH" | "ABSOLUTE"): string {
    return this.lib?.AltitudeMode?.[name] || name;
  }

  private applyRouteStyle(el: Polyline3DEl, style: RouteStyle): void {
    const casing = Math.max(0, style.casingWidth ?? 0);
    const core = Math.max(0.5, style.width);
    const total = core + 2 * casing;
    try {
      el.strokeColor = withAlpha(style.color, style.alpha);
      el.strokeWidth = total;
      if (casing > 0 && (style.casingAlpha ?? 0) > 0) {
        el.outerColor = withAlpha(style.casingColor || "#1c2f3a", style.casingAlpha ?? 0.9);
        el.outerWidth = Math.min(0.6, (2 * casing) / total);
      } else {
        el.outerWidth = 0;
      }
      if (style.zIndex != null) el.zIndex = style.zIndex;
    } catch (err) {
      console.warn("[mmd] route style failed", err);
    }
  }

  private toPath(coords: Array<[number, number] | { lng: number; lat: number }>, altitude = 0): LatLngAlt[] {
    const out: LatLngAlt[] = [];
    for (const c of coords) {
      const lng = Array.isArray(c) ? Number(c[0]) : Number(c.lng);
      const lat = Array.isArray(c) ? Number(c[1]) : Number(c.lat);
      if (Number.isFinite(lat) && Number.isFinite(lng)) out.push({ lat, lng, altitude });
    }
    return out;
  }

  private setPath(el: Polyline3DEl, path: LatLngAlt[]): void {
    if (path.length < 2) return; // Map3D throws on empty iterables
    try {
      if ("path" in el || typeof el.path !== "undefined") el.path = path;
      else el.coordinates = path;
    } catch (err) {
      console.warn("[mmd] polyline path failed", err);
    }
  }

  /** Create or update a route ribbon. Hidden routes are detached, never emptied. */
  setRoute(id: string, coords: Array<[number, number]> | null, style: RouteStyle): void {
    if (!this.el || !this.lib) return;
    let rec = this.routes.get(id);
    const path = coords ? this.toPath(coords, 1) : rec?.coords || [];
    if (!rec) {
      if (path.length < 2) return;
      const el = new this.lib.Polyline3DElement({
        altitudeMode: this.altitudeMode("CLAMP_TO_GROUND"),
        drawsOccludedSegments: true,
        geodesic: false,
      });
      rec = { el, coords: path, sig: pathSignature(path), style, attached: false, drawOnToken: 0 };
      this.routes.set(id, rec);
      this.setPath(el, path);
    } else if (coords && path.length >= 2) {
      const sig = pathSignature(path);
      if (sig !== rec.sig) {
        rec.coords = path;
        rec.sig = sig;
        if (!rec.drawOnToken) this.setPath(rec.el, path);
      }
    }
    rec.style = style;
    this.applyRouteStyle(rec.el, style);
    const wantAttached = style.visible && style.alpha > 0.01 && style.width > 0;
    if (wantAttached && !rec.attached) {
      this.el.append(rec.el);
      rec.attached = true;
    } else if (!wantAttached && rec.attached) {
      rec.el.remove();
      rec.attached = false;
    }
  }

  hasRoute(id: string): boolean {
    return this.routes.has(id);
  }

  removeRoute(id: string): void {
    const rec = this.routes.get(id);
    if (!rec) return;
    rec.el.remove();
    this.routes.delete(id);
  }

  /** "Ink" reveal — grow the ribbon from its origin over durationMs. */
  drawOn(id: string, durationMs = 1800): Promise<void> {
    const rec = this.routes.get(id);
    if (!rec || rec.coords.length < 3 || durationMs <= 0) return Promise.resolve();
    const token = ++rec.drawOnToken;
    const full = rec.coords;
    const start = performance.now();
    return new Promise((resolve) => {
      const step = () => {
        if (rec.drawOnToken !== token) {
          resolve();
          return;
        }
        const t = Math.min(1, (performance.now() - start) / durationMs);
        const eased = 1 - Math.pow(1 - t, 3);
        const n = Math.max(2, Math.round(eased * full.length));
        this.setPath(rec.el, full.slice(0, n));
        if (t >= 1) {
          rec.drawOnToken = 0;
          this.setPath(rec.el, full);
          resolve();
          return;
        }
        window.setTimeout(step, 33);
      };
      step();
    });
  }

  // ── Trail (traveled portion during Watch) ────────────────────────────────

  setTrail(coords: Array<[number, number]>, color: string): void {
    if (!this.el || !this.lib) return;
    const path = this.toPath(coords, 2);
    if (path.length < 2) return;
    this.trailPending = { coords: path, color };
    const now = performance.now();
    const due = Math.max(0, 90 - (now - this.lastTrailWrite));
    if (this.trailTimer != null) return;
    this.trailTimer = window.setTimeout(() => {
      this.trailTimer = null;
      this.flushTrail();
    }, due);
  }

  private flushTrail(): void {
    const pending = this.trailPending;
    if (!pending || !this.el || !this.lib) return;
    this.trailPending = null;
    this.lastTrailWrite = performance.now();
    if (!this.trailEl) {
      this.trailEl = new this.lib.Polyline3DElement({
        altitudeMode: this.altitudeMode("CLAMP_TO_GROUND"),
        drawsOccludedSegments: true,
        geodesic: false,
        zIndex: 50,
      });
      this.el.append(this.trailEl);
    }
    this.applyRouteStyle(this.trailEl, {
      color: pending.color,
      width: 7,
      alpha: 1,
      // Trip-colored soft outer = glow substitute on Map3D (no line-blur).
      casingColor: pending.color,
      casingWidth: 4,
      casingAlpha: 0.45,
      visible: true,
      zIndex: 50,
    });
    this.setPath(this.trailEl, pending.coords);
  }

  clearTrail(): void {
    if (this.trailTimer != null) {
      window.clearTimeout(this.trailTimer);
      this.trailTimer = null;
    }
    this.trailPending = null;
    if (this.trailEl) {
      this.trailEl.remove();
      this.trailEl = null;
    }
  }

  // ── Trail parts (playback/trail ChunkedTrail sink) ───────────────────────

  private trailSettledEl: Polyline3DEl | null = null;
  private trailHeadEl: Polyline3DEl | null = null;
  private trailPartsColor = "";
  /** Diagnostics for the perf harness. */
  readonly trailPartStats = { settledWrites: 0, headWrites: 0, settledPoints: 0, headPoints: 0 };

  private trailPartStyle(color: string): RouteStyle {
    return {
      color,
      width: 7,
      alpha: 1,
      casingColor: color,
      casingWidth: 4,
      casingAlpha: 0.45,
      visible: true,
      zIndex: 50,
    };
  }

  private ensureTrailPart(current: Polyline3DEl | null, color: string): Polyline3DEl | null {
    if (!this.el || !this.lib) return null;
    let el = current;
    if (!el) {
      el = new this.lib.Polyline3DElement({
        altitudeMode: this.altitudeMode("CLAMP_TO_GROUND"),
        drawsOccludedSegments: true,
        geodesic: false,
        zIndex: 50,
      });
      this.applyRouteStyle(el, this.trailPartStyle(color));
      this.el.append(el);
    } else if (color !== this.trailPartsColor) {
      this.applyRouteStyle(el, this.trailPartStyle(color));
    }
    return el;
  }

  /**
   * Bounded per-frame trail: the *settled* ribbon only changes every few hundred
   * vertices (`null` = unchanged, `[]` = remove); the *head* is the short stretch
   * from the last settle point to the exact tip and is rewritten per frame.
   */
  setTrailParts(settled: Array<[number, number]> | null, head: Array<[number, number]>, color: string): void {
    if (!this.el || !this.lib) return;
    if (settled) {
      if (settled.length < 2) {
        if (this.trailSettledEl) {
          this.trailSettledEl.remove();
          this.trailSettledEl = null;
        }
      } else {
        this.trailSettledEl = this.ensureTrailPart(this.trailSettledEl, color);
        if (this.trailSettledEl) {
          this.setPath(this.trailSettledEl, this.toPath(settled, 2));
          this.trailPartStats.settledWrites += 1;
          this.trailPartStats.settledPoints = settled.length;
        }
      }
    } else if (this.trailSettledEl && color !== this.trailPartsColor) {
      this.applyRouteStyle(this.trailSettledEl, this.trailPartStyle(color));
    }
    if (head.length >= 2) {
      this.trailHeadEl = this.ensureTrailPart(this.trailHeadEl, color);
      if (this.trailHeadEl) {
        this.setPath(this.trailHeadEl, this.toPath(head, 2));
        this.trailPartStats.headWrites += 1;
        this.trailPartStats.headPoints = head.length;
      }
    } else if (this.trailHeadEl) {
      this.trailHeadEl.remove();
      this.trailHeadEl = null;
    }
    this.trailPartsColor = color;
  }

  clearTrailParts(): void {
    if (this.trailSettledEl) {
      this.trailSettledEl.remove();
      this.trailSettledEl = null;
    }
    if (this.trailHeadEl) {
      this.trailHeadEl.remove();
      this.trailHeadEl = null;
    }
    this.trailPartsColor = "";
  }

  // ── Memory light pillars ─────────────────────────────────────────────────

  setPillars(points: Array<{ lat: number; lng: number; color?: string; height?: number }>): void {
    this.clearPillars();
    if (!this.el || !this.lib) return;
    const max = 48;
    for (const p of points.slice(0, max)) {
      if (!Number.isFinite(p.lat) || !Number.isFinite(p.lng)) continue;
      const h = Math.max(40, p.height ?? 140);
      try {
        const line = new this.lib.Polyline3DElement({
          altitudeMode: this.altitudeMode("RELATIVE_TO_GROUND"),
          drawsOccludedSegments: true,
          strokeColor: withAlpha(p.color || "#fbbf24", 0.72),
          strokeWidth: 3,
          outerColor: withAlpha(p.color || "#fbbf24", 0.18),
          outerWidth: 0.5,
          zIndex: 40,
        });
        this.setPath(line, [
          { lat: p.lat, lng: p.lng, altitude: 2 },
          { lat: p.lat, lng: p.lng, altitude: h },
        ]);
        this.el.append(line);
        this.pillars.push(line);
      } catch (err) {
        console.warn("[mmd] pillar failed", err);
        break;
      }
    }
  }

  clearPillars(): void {
    this.pillars.forEach((p) => p.remove());
    this.pillars = [];
  }

  // ── HTML markers ─────────────────────────────────────────────────────────

  /**
   * Host an arbitrary HTML element at a location. Uses MarkerElement (custom
   * HTML) when the API offers it, otherwise a Marker3DElement with the first
   * <img>/<svg> found inside the element (rasterized by Google).
   */
  createHtmlMarker(el: HTMLElement, opts: SceneMarkerOptions = {}): SceneMarker | null {
    if (!this.el || !this.lib) return null;
    const anchor = opts.anchor || "center";
    const [ox, oy] = opts.offset || [0, 0];
    let rotation = 0;
    const applyRotation = () => {
      if (!opts.rotateWithMap) return;
      const heading = this.el?.heading || 0;
      el.style.setProperty("--marker-rot", `${rotation - heading}deg`);
      el.style.transform = `translate(${ox}px, ${oy}px) rotate(${rotation - heading}deg)`;
    };
    if (this.lib.MarkerElement) {
      const marker = new this.lib.MarkerElement({
        position: { lat: 0, lng: 0, altitude: 0 },
        altitudeMode: this.altitudeMode("CLAMP_TO_GROUND"),
      });
      try {
        marker.anchorLeft = "-50%";
        marker.anchorTop = anchor === "bottom" ? "-100%" : "-50%";
      } catch {
        /* older builds */
      }
      if (opts.zIndex != null) marker.style.zIndex = String(opts.zIndex);
      el.style.pointerEvents = "auto";
      if (ox || oy) el.style.transform = `translate(${ox}px, ${oy}px)`;
      marker.appendChild(el);
      this.el.append(marker);
      this.markers.add(marker);
      const rot = { apply: applyRotation };
      if (opts.rotateWithMap) this.rotatingMarkers.add(rot);
      return {
        element: el,
        setPosition: (lat, lng) => {
          try {
            marker.position = { lat, lng, altitude: 0 };
          } catch {
            /* ignore */
          }
        },
        setRotation: (deg) => {
          rotation = deg || 0;
          applyRotation();
        },
        remove: () => {
          this.rotatingMarkers.delete(rot);
          this.markers.delete(marker);
          marker.remove();
        },
      };
    }
    // Fallback: rasterized image/svg marker.
    const visual = el.querySelector("img, svg");
    const marker = new this.lib.Marker3DElement({
      position: { lat: 0, lng: 0, altitude: 0 },
      altitudeMode: this.altitudeMode("CLAMP_TO_GROUND"),
      sizePreserved: true,
    });
    if (visual) {
      const tpl = document.createElement("template");
      tpl.content.appendChild(visual.cloneNode(true));
      marker.appendChild(tpl);
    }
    this.el.append(marker);
    this.markers.add(marker);
    return {
      element: el,
      setPosition: (lat, lng) => {
        try {
          marker.position = { lat, lng, altitude: 0 };
        } catch {
          /* ignore */
        }
      },
      setRotation: () => {},
      remove: () => {
        this.markers.delete(marker);
        marker.remove();
      },
    };
  }

  // ── Vehicle model ────────────────────────────────────────────────────────

  /** glTF car on the terrain; heading follows travel. Silently no-op without Model3DElement. */
  setVehicleModel(lat: number, lng: number, heading: number, mode: TravelMode | "hidden"): boolean {
    if (!this.el || !this.lib?.Model3DElement || this.vehicleOk === false) return false;
    if (mode !== "driving") {
      if (this.vehicle) this.vehicle.style.display = "none";
      return false;
    }
    try {
      if (!this.vehicle) {
        this.vehicle = new this.lib.Model3DElement({
          src: new URL(VEHICLE_MODEL_URL, document.baseURI).toString(),
          position: { lat, lng, altitude: 0 },
          altitudeMode: this.altitudeMode("CLAMP_TO_GROUND"),
          scale: 1,
        });
        this.vehicle.addEventListener("gmp-error", () => {
          this.vehicleOk = false;
          this.vehicle?.remove();
          this.vehicle = null;
          document.body.classList.remove("vehicle-model-3d");
        });
        this.el.append(this.vehicle);
        this.vehicleOk = true;
      }
      this.vehicle.style.display = "";
      this.vehicle.position = { lat, lng, altitude: 0 };
      this.vehicle.orientation = {
        heading: ((heading || 0) + VEHICLE_MODEL_ORIENTATION.heading + 360) % 360,
        tilt: VEHICLE_MODEL_ORIENTATION.tilt,
        roll: VEHICLE_MODEL_ORIENTATION.roll,
      };
      document.body.classList.add("vehicle-model-3d");
      return true;
    } catch (err) {
      console.warn("[mmd] vehicle model failed", err);
      this.vehicleOk = false;
      return false;
    }
  }

  hideVehicleModel(): void {
    if (this.vehicle) this.vehicle.style.display = "none";
    document.body.classList.remove("vehicle-model-3d");
  }

  /** Scale the model with camera range so it stays readable when the camera pulls back. */
  setVehicleScale(range: number): void {
    if (!this.vehicle) return;
    // 1× at ≤ 400 m, growing gently so the car never vanishes on aerial legs.
    const s = Math.max(1, Math.min(60, range / 400));
    try {
      this.vehicle.scale = s;
    } catch {
      /* ignore */
    }
  }

  destroy(): void {
    this.clearTrail();
    this.teardownElement();
    this.host.remove();
  }
}
